};

/**
 * @event
 * @name scwin.btn_divSendForm_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_divSendForm_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_divSendForm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.div_send_form('__self.form',(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "gubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("gubun"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "gubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("gubun")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "gubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("gubun"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "gubun" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("gubun"))))))
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf05010.btn_divSendForm_onclick' }); }
};

